from __future__ import annotations

import base64

# 192x192 PNG, blue dial glyph — used as favicon / apple-touch-icon / PWA icon
# for the rich dashboard (see /rich-dashboard-icon.png and /rich-dashboard-manifest.json).
ICON_PNG_B64 = ""


def icon_png_bytes() -> bytes:
    return base64.b64decode(ICON_PNG_B64)
